from django.contrib.auth import get_user_model
from django.contrib.auth.decorators import login_required
from django.core.cache import cache
from django.shortcuts import get_object_or_404, redirect, render
from django.views.decorators.http import require_POST
from taggit.models import Tag

from articles.forms import ArticleForm
from articles.models import Article
from helpers.htmx import is_htmx

User = get_user_model()

ARTICLES_PER_PAGE = 10


def _build_feed(request, tag=None):
    """Shared logic for home and tag views."""
    feed = request.GET.get("feed")
    try:
        page = int(request.GET.get("page", 1))
    except (ValueError, TypeError):
        page = 1
    offset = (page - 1) * ARTICLES_PER_PAGE

    queryset = Article.objects.with_favorites(request.user)

    if feed == "following" and not request.user.is_authenticated:
        return redirect("login")
    if feed == "following" and request.user.is_authenticated:
        followed_authors = User.objects.filter(followers=request.user)
        queryset = queryset.filter(author__in=followed_authors)
        active_tab = "following"
    elif tag:
        queryset = queryset.filter(tags__name=tag)
        active_tab = "tag"
    else:
        active_tab = "global"

    queryset = queryset.select_related("author").prefetch_related("tags").order_by("-created")
    total = queryset.count()
    articles = list(queryset[offset : offset + ARTICLES_PER_PAGE])
    total_pages = (total + ARTICLES_PER_PAGE - 1) // ARTICLES_PER_PAGE
    pages = range(1, total_pages + 1)

    tags = cache.get_or_set("all_tags", Tag.objects.all, timeout=300)

    context = {
        "articles": articles,
        "tags": tags,
        "active_tab": active_tab,
        "active_tag": tag,
        "page": page,
        "pages": pages,
    }

    if is_htmx(request):
        return render(request, "partials/feed_content.html", context)
    return render(request, "articles/home.html", context)


def home_view(request):
    tag = request.GET.get("tag")
    return _build_feed(request, tag=tag)


def tag_view(request, tag):
    return _build_feed(request, tag=tag)


def article_detail_view(request, slug):
    try:
        article = (
            Article.objects.with_favorites(request.user)
            .select_related("author")
            .prefetch_related("tags")
            .get(slug=slug)
        )
    except Article.DoesNotExist:
        return render(request, "articles/detail_404.html", {"slug": slug}, status=404)
    comments = article.comment_set.select_related("author").order_by("-created")
    is_following = request.user.is_authenticated and request.user.is_following(article.author)
    return render(
        request,
        "articles/detail.html",
        {
            "article": article,
            "comments": comments,
            "is_following": is_following,
        },
    )


def _save_article_form(form, article):
    """Map form fields (description/body) to model fields (summary/content) and save."""
    article.title = form.cleaned_data["title"]
    article.summary = form.cleaned_data.get("description", "")
    article.content = form.cleaned_data.get("body", "")
    article.save()
    tag_string = form.cleaned_data.get("tags", "")
    article.tags.clear()
    if tag_string:
        for tag_name in tag_string.split(","):
            tag_name = tag_name.strip()
            if tag_name:
                article.tags.add(tag_name)
    cache.delete("all_tags")


@login_required
def article_create_view(request):
    if request.method == "POST":
        form = ArticleForm(request.POST)
        if form.is_valid():
            article = Article(author=request.user)
            _save_article_form(form, article)
            return redirect("article_detail", slug=article.slug)
    else:
        form = ArticleForm()
    return render(request, "articles/editor.html", {"form": form})


@login_required
def article_edit_view(request, slug):
    article = get_object_or_404(Article, slug=slug, author=request.user)
    if request.method == "POST":
        form = ArticleForm(request.POST)
        if form.is_valid():
            _save_article_form(form, article)
            return redirect("article_detail", slug=article.slug)
    else:
        form = ArticleForm(
            initial={
                "title": article.title,
                "description": article.summary,
                "body": article.content,
                "tags": ", ".join(t.name for t in article.tags.all()),
            }
        )
    return render(request, "articles/editor.html", {"form": form, "article": article})


@login_required
@require_POST
def article_delete_view(request, slug):
    article = get_object_or_404(Article, slug=slug, author=request.user)
    article.delete()
    return redirect("home")


@login_required
@require_POST
def article_favorite_view(request, slug):
    article = get_object_or_404(Article, slug=slug)
    if article.favorites.filter(id=request.user.id).exists():
        article.favorites.remove(request.user)
    else:
        article.favorites.add(request.user)
    article = Article.objects.with_favorites(request.user).select_related("author").get(pk=article.pk)
    if is_htmx(request):
        return render(request, "partials/favorite_button.html", {"article": article})
    return redirect("article_detail", slug=slug)

from django import forms


class ArticleForm(forms.Form):
    """Article editor form with field names matching the RealWorld SELECTORS.md spec."""

    title = forms.CharField(
        max_length=150,
        widget=forms.TextInput(attrs={"class": "form-control form-control-lg", "placeholder": "Article Title"}),
    )
    description = forms.CharField(
        required=False,
        widget=forms.TextInput(attrs={"class": "form-control", "placeholder": "What's this article about?"}),
    )
    body = forms.CharField(
        required=False,
        widget=forms.Textarea(
            attrs={"class": "form-control", "placeholder": "Write your article (in markdown)", "rows": 8}
        ),
    )
    tags = forms.CharField(
        required=False,
        widget=forms.HiddenInput(),
    )

from articles.models import Article
from django.contrib.auth import authenticate, get_user_model, login, logout
from django.contrib.auth.decorators import login_required
from django.db import IntegrityError, transaction
from django.shortcuts import get_object_or_404, redirect, render
from django.views.decorators.http import require_POST

from accounts.forms import LoginForm, RegisterForm, SettingsForm
from helpers.exceptions import clean_integrity_error
from helpers.htmx import is_htmx

ARTICLES_PER_PAGE = 10

User = get_user_model()


def login_view(request):
    if request.method == "POST":
        form = LoginForm(request.POST)
        if form.is_valid():
            user = authenticate(email=form.cleaned_data["email"], password=form.cleaned_data["password"])
            if user is not None:
                login(request, user)
                return redirect("home")
            form.add_error(None, "Invalid email or password.")
    else:
        form = LoginForm()
    return render(request, "accounts/login.html", {"form": form})


def register_view(request):
    if request.method == "POST":
        form = RegisterForm(request.POST)
        if form.is_valid():
            try:
                with transaction.atomic():
                    user = User.objects.create_user(
                        email=form.cleaned_data["email"],
                        username=form.cleaned_data["username"],
                        password=form.cleaned_data["password"],
                    )
                login(request, user)
                return redirect("home")
            except IntegrityError as err:
                field = clean_integrity_error(err)
                if field == "email":
                    form.add_error("email", "This email has already been taken.")
                elif field == "username":
                    form.add_error("username", "This username has already been taken.")
                else:
                    form.add_error(None, "Registration failed.")
    else:
        form = RegisterForm()
    return render(request, "accounts/register.html", {"form": form})


@login_required
def settings_view(request):
    if request.method == "POST":
        form = SettingsForm(request.POST, instance=request.user)
        if form.is_valid():
            user = form.save(commit=False)
            password = form.cleaned_data.get("password")
            if password:
                user.set_password(password)
            user.save()
            if password:
                login(request, user)
            return redirect("profile", username=user.username)
    else:
        form = SettingsForm(instance=request.user)
    return render(request, "accounts/settings.html", {"form": form})


@require_POST
def logout_view(request):
    logout(request)
    return redirect("home")


def _profile_view(request, username, *, tab):
    try:
        profile_user = User.objects.get(username=username)
    except User.DoesNotExist:
        return render(request, "accounts/profile_404.html", {"username": username}, status=404)

    try:
        page = int(request.GET.get("page", 1))
    except (ValueError, TypeError):
        page = 1
    offset = (page - 1) * ARTICLES_PER_PAGE

    is_self = request.user == profile_user
    is_following = request.user.is_authenticated and request.user.is_following(profile_user)
    queryset = Article.objects.with_favorites(request.user).select_related("author").prefetch_related("tags")
    if tab == "favorites":
        queryset = queryset.filter(favorites=profile_user)
    else:
        queryset = queryset.filter(author=profile_user)
    queryset = queryset.order_by("-created")
    total = queryset.count()
    articles = list(queryset[offset : offset + ARTICLES_PER_PAGE])
    total_pages = (total + ARTICLES_PER_PAGE - 1) // ARTICLES_PER_PAGE
    pages = range(1, total_pages + 1)

    return render(
        request,
        "accounts/profile.html",
        {
            "profile_user": profile_user,
            "is_self": is_self,
            "is_following": is_following,
            "articles": articles,
            "tab": tab,
            "page": page,
            "pages": pages,
        },
    )


def profile_view(request, username):
    return _profile_view(request, username, tab="my")


def profile_favorites_view(request, username):
    return _profile_view(request, username, tab="favorites")


@login_required
@require_POST
def follow_view(request, username):
    profile_user = get_object_or_404(User, username=username)
    if profile_user != request.user:
        if profile_user.followers.filter(pk=request.user.id).exists():
            profile_user.followers.remove(request.user)
            is_following = False
        else:
            profile_user.followers.add(request.user)
            is_following = True
    else:
        is_following = False
    if is_htmx(request):
        return render(
            request,
            "partials/follow_button.html",
            {
                "profile_user": profile_user,
                "is_following": is_following,
            },
        )
    return redirect("profile", username=username)

