import { test, expect, Page } from '@playwright/test';
import { register, generateUniqueUser } from './helpers/auth';
import { generateUniqueArticle, ArticleData } from './helpers/articles';

/**
 * Create an article as a draft by unchecking the "publish" toggle in the editor
 * before submitting. Returns the new article's slug.
 */
async function createDraft(page: Page, article: ArticleData): Promise<string> {
  await page.goto('/editor', { waitUntil: 'load' });

  await page.fill('input[name="title"]', article.title);
  await page.fill('input[name="description"]', article.description);
  await page.fill('textarea[name="body"]', article.body);

  // Uncheck the publish toggle so the article is saved as a draft.
  await page.uncheck('#publish-checkbox');

  await Promise.all([
    page.waitForURL(/\/article\/.+/),
    page.click('button:has-text("Publish Article")'),
  ]);

  return page.url().split('/article/')[1];
}

test.describe('Article drafts', () => {
  test('a draft is hidden from the public but visible to its author', async ({ page, browser }) => {
    const author = generateUniqueUser();
    await register(page, author.username, author.email, author.password);

    const article = generateUniqueArticle();
    const slug = await createDraft(page, article);

    // The author lands on their own draft, which is clearly marked as a Draft.
    await expect(page.locator('h1')).toContainText(article.title);
    await expect(page.getByTestId('draft-badge')).toBeVisible();

    // The draft does not show up in the global feed.
    await page.goto('/', { waitUntil: 'load' });
    await expect(page.locator('.article-preview', { hasText: article.title })).toHaveCount(0);

    // It is absent from the author's public "My Articles" tab...
    await page.goto(`/profile/${author.username}`, { waitUntil: 'load' });
    await expect(page.locator('.article-preview', { hasText: article.title })).toHaveCount(0);

    // ...but present on the author's own "Drafts" tab.
    await page.goto(`/profile/${author.username}/drafts`, { waitUntil: 'load' });
    await expect(page.locator('.article-preview', { hasText: article.title })).toHaveCount(1);

    // A different visitor cannot reach the draft by URL — it 404s as if it does not exist.
    const guestContext = await browser.newContext();
    const guestPage = await guestContext.newPage();
    await guestPage.goto(`/article/${slug}`, { waitUntil: 'load' });
    await expect(guestPage.locator('h1')).toHaveText('Article not found');
    await guestContext.close();
  });

  test('publishing a draft makes it public', async ({ page }) => {
    const author = generateUniqueUser();
    await register(page, author.username, author.email, author.password);

    const article = generateUniqueArticle();
    const slug = await createDraft(page, article);

    // Publish the draft from the editor by re-checking the publish toggle.
    await page.goto(`/editor/${slug}`, { waitUntil: 'load' });
    await expect(page.locator('input[name="title"]')).not.toHaveValue('', { timeout: 10000 });
    await page.check('#publish-checkbox');
    await Promise.all([
      page.waitForURL(/\/article\/.+/),
      page.click('button:has-text("Publish Article")'),
    ]);

    // No longer marked as a draft.
    await expect(page.getByTestId('draft-badge')).toHaveCount(0);

    // Now visible in the global feed.
    await page.goto('/', { waitUntil: 'load' });
    await expect(page.locator('.article-preview', { hasText: article.title })).toHaveCount(1);

    // Listed under the author's public "My Articles", and no longer under "Drafts".
    await page.goto(`/profile/${author.username}`, { waitUntil: 'load' });
    await expect(page.locator('.article-preview', { hasText: article.title })).toHaveCount(1);
    await page.goto(`/profile/${author.username}/drafts`, { waitUntil: 'load' });
    await expect(page.locator('.article-preview', { hasText: article.title })).toHaveCount(0);
  });
});
